ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	doValidarEquiposPremisaInstalar: {
		PeticionValidarEquiposPremisaInstalar: {
			EncabezadoMensaje: {
				IdDisponibilidad: payload.validatePremiseEquipmentInstall.messageHeader.availabilityId,
				NumeroOrdenAprovisionador: payload.validatePremiseEquipmentInstall.messageHeader.provisioningOrderNumber,
				NumeroRevision: payload.validatePremiseEquipmentInstall.messageHeader.revisionNumber,
				FechaPeticionOrden: payload.validatePremiseEquipmentInstall.messageHeader.orderRequestDate,
				TecnologiaETB: payload.validatePremiseEquipmentInstall.messageHeader.etbTechnology
			},
			DetalleMensaje: {
				Direccion: {
					CodigoUnicoDireccion: payload.validatePremiseEquipmentInstall.detail.address.uniqueAddressCode,
					IdCuentaServicio: payload.validatePremiseEquipmentInstall.detail.address.serviceAccountId,
					Equipos: payload.validatePremiseEquipmentInstall.detail.address.equipments map (eq) -> {
						IdServicio: eq.serviceId,
						SerialEquipo: eq.equipmentSerial,
						MacEquipo: eq.equipmentMac,
						Puertos: eq.ports map (p) -> {
							NombrePuerto: p.portName,
							ServiciosPuerto: {
								IdServicioPuerto: p.portServices.portServiceId
							}
						},
						EquipoInstalado: eq.installedEquipment
					}
				}
			}
		}
	}
}

%dw 2.0
output application/json
var src = payload.objConfiguracionInventario
var code = payload.cod_res as Number
---
{
	status: code,
	code: if ( code == 200 ) "OK" else "Error",
	message: {
		message: if ( code == 200 ) "Successful Transaction." else "Error Transaction."
	},
	validatePremiseEquipmentInstall: {
		messageHeader: {
			availabilityId: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.EncabezadoMensaje.IdDisponibilidad,
			provisioningOrderNumber: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.EncabezadoMensaje.NumeroOrdenAprovisionador,
			revisionNumber: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.EncabezadoMensaje.NumeroRevision,
			orderRequestDate: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.EncabezadoMensaje.FechaPeticionOrden
		},
		detail: {
			equipment: {
				equipmentBrand: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.DetalleMensaje.Equipo.MarcaEquipo,
				serviceId: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.DetalleMensaje.Equipo.IdServicio,
				obsolescenceIndicator: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.DetalleMensaje.Equipo.IndicadorObsolescencia,
				equipmentSerial: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.DetalleMensaje.Equipo.SerialEquipo,
				equipmentMac: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.DetalleMensaje.Equipo.MacEquipo,
				equipmentType: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.DetalleMensaje.Equipo.TipoEquipo,
				equipmentModel: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.DetalleMensaje.Equipo.ModeloEquipo,
				compatibilityIndicator: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.DetalleMensaje.Equipo.IndicadorCompatibilidad,
				compatibilityResponse: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.DetalleMensaje.Equipo.RespuestaCompatibilidad,
				attributes: payload.doValidarEquiposPremisaInstalarResponse.RespuestaPeticionValidarEquiposPremisaInstalar.DetalleMensaje.Equipo.Atributos map (att) -> {
					attribute: att.Atributo,
					value: att.Valor
				}
			}
		}
	}
}
